var n=`0112-mulgipuder`;var t=`world-0112`;var a=`EE`;var o=`northern-europe`;var s=4;var r=54;var l={en:`Mulgipuder`,ua:`Мульгіпудер`};var g={en:`A classic dish from Estonia, featuring potato, pearl barley, bacon, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Естонія. Основні складники: картопля, перлова крупа, бекон, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 35 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 35 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:35,i:[[`potato`,700,`g`],[`pearl-barley`,175,`g`],[`water`,1300,`ml`],[`table-salt`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`bacon`,220,`g`],[`yellow-onion`,190,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`unsalted-butter`,45,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,130,`g`]]}];var u={slug:n,id:t,country:`EE`,region:o,servings:4,minutes:54,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};